"use client";

import { useEffect, useState } from "react";
import { Plus, X } from "lucide-react";

interface Vendor { id: string; name: string; serviceType: string; phone: string; email?: string }
const SERVICES = ["PLUMBING", "ELECTRICAL", "CLEANING", "HVAC", "SECURITY", "GENERAL", "OTHER"];
const empty = { name: "", phone: "", serviceType: "GENERAL", email: "" };

export default function VendorsPage() {
  const [vendors, setVendors] = useState<Vendor[]>([]); const [form, setForm] = useState(empty); const [open, setOpen] = useState(false); const [error, setError] = useState("");
  const load = async () => { try { const response = await fetch("/api/real-estate/vendors?limit=100", { credentials: "include" }); const data = await response.json(); if (!response.ok) throw new Error(data.error || "Unable to load vendors"); setVendors(data.vendors || []); } catch (e: unknown) { setError(e instanceof Error ? e.message : "Unable to load vendors"); } };
  useEffect(() => { void load(); }, []);
  const save = async (event: React.FormEvent) => { event.preventDefault(); setError(""); try { const response = await fetch("/api/real-estate/vendors", { method: "POST", credentials: "include", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ name: form.name, phone: form.phone, serviceType: form.serviceType, email: form.email || undefined }) }); const data = await response.json(); if (!response.ok) throw new Error(data.error || "Unable to save vendor"); setOpen(false); setForm(empty); await load(); } catch (e: unknown) { setError(e instanceof Error ? e.message : "Unable to save vendor"); } };
  return <div><div className="flex items-center justify-between mb-6"><div><h2 className="text-2xl font-extrabold text-slate-900">Vendors</h2><p className="text-slate-500 text-sm">Service providers for maintenance and repairs.</p></div><button onClick={() => setOpen(true)} className="inline-flex items-center gap-2 bg-blue-600 text-white font-semibold px-4 py-2.5 rounded-xl text-sm cursor-pointer"><Plus size={16} /> Add Vendor</button></div>{error && <div className="mb-4 p-3 rounded-xl bg-red-50 border border-red-200 text-red-700 text-sm">{error}</div>}<div className="bg-white border border-slate-200 rounded-xl overflow-x-auto"><table className="w-full min-w-[600px]"><thead><tr className="bg-slate-50 border-b border-slate-200"><th className="text-left px-4 py-3 text-xs uppercase text-slate-500">Name</th><th className="text-left px-4 py-3 text-xs uppercase text-slate-500">Service</th><th className="text-left px-4 py-3 text-xs uppercase text-slate-500">Phone</th><th className="text-left px-4 py-3 text-xs uppercase text-slate-500">Email</th></tr></thead><tbody>{vendors.length === 0 ? <tr><td colSpan={4} className="px-4 py-8 text-center text-slate-400 text-sm">No vendors added yet.</td></tr> : vendors.map((vendor) => <tr key={vendor.id} className="border-b border-slate-100"><td className="px-4 py-3 text-sm font-semibold text-slate-900">{vendor.name}</td><td className="px-4 py-3"><span className="text-xs font-semibold px-2 py-1 rounded-full bg-blue-50 text-blue-700">{vendor.serviceType}</span></td><td className="px-4 py-3 text-sm text-slate-600">{vendor.phone}</td><td className="px-4 py-3 text-sm text-slate-600">{vendor.email || "—"}</td></tr>)}</tbody></table></div>{open && <div className="fixed inset-0 z-50 bg-black/40 grid place-items-center p-4"><form onSubmit={save} className="bg-white rounded-2xl w-full max-w-md p-6 space-y-3"><div className="flex justify-between items-center"><h3 className="font-bold text-lg">Add Vendor</h3><button type="button" onClick={() => setOpen(false)} className="border-none bg-transparent text-slate-400 cursor-pointer"><X size={18} /></button></div><input required placeholder="Vendor name" value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} className="w-full border border-slate-200 rounded-xl px-3 py-2.5 text-sm" /><div className="grid grid-cols-2 gap-3"><input required placeholder="Phone" value={form.phone} onChange={(e) => setForm({ ...form, phone: e.target.value })} className="border border-slate-200 rounded-xl px-3 py-2.5 text-sm" /><select value={form.serviceType} onChange={(e) => setForm({ ...form, serviceType: e.target.value })} className="w-full border border-slate-200 rounded-xl px-3 py-2.5 text-sm bg-white">{SERVICES.map((service) => <option key={service} value={service}>{service}</option>)}</select></div><input type="email" placeholder="Email (optional)" value={form.email} onChange={(e) => setForm({ ...form, email: e.target.value })} className="w-full border border-slate-200 rounded-xl px-3 py-2.5 text-sm" /><button className="w-full bg-blue-600 text-white rounded-xl py-2.5 font-semibold text-sm cursor-pointer">Save Vendor</button></form></div>}</div>;
}
